<?php
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Access,Business,Ctx,Db,Jalali,Money,Request,Settings,ValidationException};
use Agah\Erp\Modules\Files\FileService;
use Agah\Erp\Modules\Payroll\PayrollService;
use Agah\Erp\Modules\Assets\AssetService;
if(!defined('ABSPATH'))exit;
final class OperationsController {
    private static $upload;
    public static function nav(){return LegalController::nav()+['files'=>['پیوست‌های خصوصی','file.view'],'payroll_employees'=>['کارکنان','payroll.view'],'payroll_contracts'=>['قراردادهای کار','payroll.view'],'payroll_attendance'=>['کارکرد و مرخصی','payroll.view'],'payroll_params'=>['پارامترهای سالانه حقوق','payroll.view'],'payroll_slips'=>['فیش و گزارش حقوق','payroll.view'],'assets'=>['دفتر دارایی ثابت','asset.view']];}
    public static function cap($p){if(LegalController::cap($p))return LegalController::cap($p);return ['payslip_view'=>'payroll.view','asset_view'=>'asset.view','asset_new'=>'asset.create'][$p]??(self::nav()[$p][1]??null);}
    public static function actions(){return LegalController::actions()+['module_file_attach'=>'file.create','module_file_delete'=>'file.delete','module_payroll_employee'=>Request::int('post','id')?'payroll.edit':'payroll.create','module_payroll_contract'=>'payroll.edit','module_payroll_attendance'=>'payroll.edit','module_payroll_params'=>'payroll.edit','module_payroll_issue'=>'payroll.approve','module_payroll_void'=>'payroll.delete','module_asset_acquire'=>'asset.create','module_asset_depreciate'=>'asset.approve','module_asset_dispose'=>'asset.approve','module_asset_void'=>'asset.delete'];}
    public static function preflight($p,$cid){if(LegalController::preflight($p,$cid))return true;$cap=self::cap($p);if(!$cap)return false;Access::need($cid,$cap);if($p==='payslip_view')PayrollService::get($cid,Request::int('get','id'));if($p==='asset_view')AssetService::get($cid,Request::int('get','id'));if(Request::int('get','edit')&&in_array($p,['payroll_employees','payroll_contracts'],true))Business::row($p==='payroll_employees'?'employees':'contracts',$cid,Request::int('get','edit'));return true;}
    public static function view($p){if(LegalController::view($p))return LegalController::view($p);return ['files'=>'operations-files','payroll_employees'=>'operations-employees','payroll_contracts'=>'operations-contracts','payroll_attendance'=>'operations-attendance','payroll_params'=>'operations-params','payroll_slips'=>'operations-slips','payslip_view'=>'operations-payslip','assets'=>'operations-assets','asset_new'=>'operations-asset-form','asset_view'=>'operations-asset'][$p]??null;}
    public static function upload(){if(self::$upload!==null)return self::$upload;if(!\Agah\Erp\Security\RateLimiter::consume('file-upload|'.Ctx::uid().'|'.Ctx::cid(),30,3600))throw new ValidationException(['file'=>'سقف ۳۰ تلاش بارگذاری در ساعت پر شده است.']);$f=$_FILES['attachment']??null;$max=max(1,min(10,Settings::int('max_upload_mb')))*1048576;if(!is_array($f)||($f['error']??1)!==UPLOAD_ERR_OK||!is_string($f['tmp_name']??null)||!is_uploaded_file($f['tmp_name'])||($f['size']??0)>$max||!is_string($f['name']??null))throw new ValidationException(['file'=>'آپلود واقعی و در محدوده حجم لازم است.']);$bytes=file_get_contents($f['tmp_name'],false,null,0,$max+1);if($bytes===false)throw new ValidationException(['file'=>'خواندن فایل ناموفق بود.']);return self::$upload=['name'=>$f['name'],'bytes'=>$bytes];}
    private static function money($k){return Money::fromInput(Request::str('post',$k,40),Ctx::unit());}
    public static function dispatch($act,$cid,$url){$id=Request::int('post','id');switch($act){
        case 'module_file_attach':$u=self::upload();FileService::attach($cid,Request::str('post','target_type',10),Request::int('post','target_id'),$u['name'],$u['bytes'],Request::str('post','category',80));return $url;
        case 'module_file_delete':FileService::remove($cid,$id);return $url;
        case 'module_payroll_employee':PayrollService::employee($cid,$id,['name'=>Request::str('post','name',190),'code'=>Request::str('post','code',30),'is_active'=>Request::flag('post','is_active')]);return $url;
        case 'module_payroll_contract':$in=['employee_id'=>Request::int('post','employee_id')];foreach(['start_date','end_date'] as $k)$in[$k]=Jalali::parse(Request::str('post',$k,10));foreach(['base_salary','benefits','benefits_insurance_exempt','benefits_tax_exempt','overtime_base_extra','hourly_rate','project_amount'] as $k)$in[$k]=self::money($k);$in['contract_type']=Request::str('post','contract_type',10,'full');$in['weekly_minutes']=Request::int('post','weekly_minutes');$in['items']=Phase2Controller::itemsInput(Request::text('post','items',2000));PayrollService::contract($cid,$id,$in);return $url;
        case 'module_payroll_attendance':$in=['period_key'=>Request::str('post','period_key',7),'employee_id'=>Request::int('post','employee_id')];foreach(['work_days','leave_days','overtime_minutes','mission_days','absence_days','work_minutes'] as $k)$in[$k]=Request::int('post',$k);$pp=Money::normDigits(Request::str('post','project_percent',6));if($pp!==''){if(!preg_match('/^(\d{1,3})(?:\.(\d))?$/D',$pp,$mm)||(int)$mm[1]*10+(int)($mm[2]??0)>1000)throw new ValidationException(['project_percent'=>'درصد پیشرفت بین ۰ تا ۱۰۰ با حداکثر یک رقم اعشار.']);$in['project_permille']=(int)$mm[1]*10+(int)($mm[2]??0);}foreach(['extra_benefits','deductions','extra_insurance_exempt','extra_tax_exempt'] as $k)$in[$k]=self::money($k);PayrollService::attendance($cid,$in);return $url;
        case 'module_payroll_params':$p=[];foreach(['employee_bp','employer_bp'] as $k)$p[$k]=Money::pctBp(Request::str('post',$k,10));$percent=Money::normDigits(Request::str('post','overtime_percent',10));if(!preg_match('/^(\d{1,3})(?:\.(\d{1,2}))?$/D',$percent,$m))throw new ValidationException(['overtime_percent'=>'ضریب اضافه‌کار معتبر نیست.']);$p['overtime_bp']=(int)$m[1]*100+(int)str_pad($m[2]??'',2,'0');$p['insurance_tax_numerator']=Request::int('post','insurance_tax_numerator',1);$p['insurance_tax_denominator']=Request::int('post','insurance_tax_denominator',1);$p['monthly_minutes']=Request::int('post','monthly_minutes');foreach(['insurance_ceiling','tax_exemption'] as $k)$p[$k]=self::money($k);foreach(['expense_account_id','salary_account_id','insurance_account_id','tax_account_id','deduction_account_id'] as $k)$p[$k]=Request::int('post',$k);$p['brackets']=[];for($i=0;$i<8;$i++){if(Request::str('post','rate_'.$i,10)==='')continue;$upper=Request::str('post','upper_'.$i,40);$p['brackets'][]=['upper'=>$upper===''?null:self::money('upper_'.$i),'rate_bp'=>Money::pctBp(Request::str('post','rate_'.$i,10))];}PayrollService::params($cid,Request::int('post','year_id'),$p);return $url;
        case 'module_payroll_issue':$id=PayrollService::issue($cid,Request::int('post','employee_id'),Request::str('post','period_key',7),Jalali::parse(Request::str('post','doc_date',10)));break;
        case 'module_payroll_void':PayrollService::voidDocument($cid,$id,Request::str('post','reason',300));break;
        case 'module_asset_acquire':$in=[];foreach(['name','code','method'] as $k)$in[$k]=Request::str('post',$k,190);foreach(['acquired_date','start_date'] as $k)$in[$k]=Jalali::parse(Request::str('post',$k,10));foreach(['cost','residual'] as $k)$in[$k]=self::money($k);foreach(['life_months','asset_account_id','contra_account_id','expense_account_id','account_id','detail_id'] as $k)$in[$k]=Request::int('post',$k);$in['annual_bp']=Money::pctBp(Request::str('post','annual_percent',10));$id=AssetService::acquire($cid,$in);return agah_erp_url(['c'=>$cid,'p'=>'asset_view','id'=>$id]);
        case 'module_asset_depreciate':AssetService::depreciate($cid,$id,Request::str('post','period_key',7));return agah_erp_url(['c'=>$cid,'p'=>'asset_view','id'=>$id]);
        case 'module_asset_dispose':AssetService::dispose($cid,$id,['doc_date'=>Jalali::parse(Request::str('post','doc_date',10)),'proceeds'=>self::money('proceeds'),'account_id'=>Request::int('post','account_id'),'detail_id'=>Request::int('post','detail_id'),'result_account_id'=>Request::int('post','result_account_id')]);return agah_erp_url(['c'=>$cid,'p'=>'asset_view','id'=>$id]);
        case 'module_asset_void':$event=Business::row('asset_events',$cid,$id);AssetService::voidEvent($cid,$id,Request::str('post','reason',300));return agah_erp_url(['c'=>$cid,'p'=>'asset_view','id'=>$event['asset_id']]);
        default:return LegalController::dispatch($act,$cid,$url);
    }return agah_erp_url(['c'=>$cid,'p'=>'payslip_view','id'=>$id]);}
    public static function fileUrl($cid,$id,$preview=false){return agah_erp_url(['c'=>$cid,'p'=>'files','file_download'=>$id,'preview'=>$preview?1:0,'_n'=>wp_create_nonce('agah_file_'.$cid.'_'.$id)]);}
    public static function output($cid){$id=Request::int('get','file_download');if($id){if(!wp_verify_nonce(Request::str('get','_n',100),'agah_file_'.$cid.'_'.$id))throw new ValidationException(['file'=>'اعتبار دانلود منقضی شده است.']);$r=FileService::get($cid,$id);$preview=Request::flag('get','preview')&&strpos($r['mime'],'image/')===0;header('Content-Type: '.$r['mime']);header('Content-Length: '.strlen($r['file_data']));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');header("Content-Security-Policy: sandbox; default-src 'none'");$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'][$r['mime']];header('Content-Disposition: '.($preview?'inline':'attachment').'; filename="'.$r['stored_name'].'.'.$ext.'"');echo $r['file_data'];return;}
        $type=Request::str('get','operations_export',10);if(!in_array($type,['payroll','assets'],true))throw new ValidationException(['export'=>'نوع خروجی معتبر نیست.']);$res=$type==='payroll'?'payroll':'asset';Access::need($cid,$res.'.export');if(!wp_verify_nonce(Request::str('get','_n',100),'agah_ops_export_'.$cid.'_'.$type))throw new ValidationException(['export'=>'اعتبار خروجی منقضی است.']);Db::tx(function()use($cid,$type){$data=$type==='payroll'?PayrollService::report($cid,self::yearId($cid)):AssetService::page($cid);$keys=$type==='payroll'?['number','employee_id','period_key','doc_date','status','gross','net','tax','insurance_employee','insurance_employer']:['code','name','acquired_date','status','cost','accum','book_value'];if(($data['count']??0)>10000||$data['pages']>200)throw new ValidationException(['export'=>'بازه خروجی را کوتاه کنید.']);$rows=[];for($page=1;$page<=max(1,$data['pages']);$page++){if($page>1)$data=$type==='payroll'?PayrollService::report($cid,self::yearId($cid),$page):AssetService::page($cid,$page);foreach($data['rows'] as $r){$row=[];foreach($keys as $k)$row[]=\Agah\Erp\Core\Tabular::cell($k,$r[$k]??'');$rows[]=$row;}}\Agah\Erp\Core\Tabular::download('agah-'.$type,$keys,$rows);});
    }
    /** Human-readable source choices; a user never has to guess a database ID. Bounded and permission-filtered. */
    public static function targets($cid,$type,$q='',$selected=0){
        Access::need($cid,'file.create');if(!isset(FileService::TARGETS[$type]))return [];global $wpdb;$table=FileService::TARGETS[$type];$args=[$cid];$where='company_id=%d';
        if($type==='invoice'){$kinds=[];foreach(\Agah\Erp\Modules\Trade\InvoiceService::KINDS as $kind=>$label){$res=\Agah\Erp\Modules\Trade\InvoiceService::resource($kind);if(Ctx::can($res.'.view')&&Ctx::can($res.'.edit'))$kinds[]="'".$kind."'";}if(!$kinds)return []; $where.=' AND kind IN ('.implode(',',$kinds).')';}
        elseif(!Ctx::can($type.'.view')||!Ctx::can($type.'.edit'))return [];
        $q=Request::clean($q,100);if($q!==''){if($type==='party'){$like='%'.$wpdb->esc_like($q).'%';$where.=' AND (name LIKE %s OR code LIKE %s)';$args[]=$like;$args[]=$like;}else{$where.=' AND (description LIKE %s OR number=%d)';$args[]='%'.$wpdb->esc_like($q).'%';$args[]=ctype_digit(Money::normDigits($q))?(int)Money::normDigits($q):-1;}}
        $columns=$type==='party'?'id,name,code':($type==='invoice'?'id,number,kind,invoice_date,description':($type==='voucher'?'id,number,voucher_date,description':'id,number,kind,doc_date,description'));
        $rows=Db::rows('SELECT '.$columns.' FROM '.Db::t($table).' WHERE '.$where.' ORDER BY id DESC LIMIT 100',...$args);
        if($selected){FileService::target($cid,$type,$selected,true);FileService::target($cid,$type,$selected);$rows[]=Business::row($table,$cid,$selected);}
        $out=[0=>'رکورد مبدأ را انتخاب کنید'];foreach($rows as $r){if($type==='party')$label=$r['code'].' — '.$r['name'];else{$date=$r['invoice_date']??($r['voucher_date']??$r['doc_date']);$label=($r['number']===null?'پیش‌نویس':('شماره '.$r['number'])).' — '.Jalali::format($date).' — '.$r['description'];if($type==='invoice')$label=\Agah\Erp\Modules\Trade\InvoiceService::KINDS[$r['kind']].' — '.$label;}$out[$r['id']]=$label;}return $out;
    }
    public static function employees($cid){Access::need($cid,'payroll.view');$out=[];foreach(Db::rows('SELECT id,code,name FROM '.Db::t('employees').' WHERE company_id=%d ORDER BY code',$cid) as $r)$out[$r['id']]=$r['code'].' — '.$r['name'];return $out;}
    public static function accounts($cid,array $classes){$out=[0=>'انتخاب حساب'];$allowed=[];foreach(\Agah\Erp\Modules\Accounting\ChartSeed::classes() as $k=>$v)if(in_array($k,$classes,true))$allowed[]="'".$k."'";if(!$allowed)return $out;foreach(Db::rows('SELECT id,code,name FROM '.Db::t('accounts').' WHERE company_id=%d AND level=3 AND is_active=1 AND stmt_class IN ('.implode(',',$allowed).') ORDER BY code',$cid) as $r)$out[$r['id']]=$r['code'].' — '.$r['name'];return $out;}
    public static function yearId($cid){return isset($_GET['year_id'])?Request::int('get','year_id'):(int)(\Agah\Erp\Core\FiscalContext::selected($cid)['id']??0);}
    public static function years($cid){$out=[];foreach(Db::rows('SELECT id,title FROM '.Db::t('fiscal_years').' WHERE company_id=%d ORDER BY start_date DESC',$cid) as $r)$out[$r['id']]=$r['title'];return $out;}
    public static function details($cid){$out=[0=>'بدون تفصیلی'];foreach(Db::rows('SELECT id,code,name FROM '.Db::t('details').' WHERE company_id=%d AND is_active=1 ORDER BY code',$cid) as $r)$out[$r['id']]=$r['code'].' — '.$r['name'];return $out;}
    public static function exportLink($cid,$type){if(Ctx::can(($type==='payroll'?'payroll':'asset').'.export'))foreach(['csv'=>'CSV','xlsx'=>'Excel XLSX'] as $format=>$label)echo '<a class="btn btn-outline" href="'.esc_url(add_query_arg(['operations_export'=>$type,'format'=>$format,'_n'=>wp_create_nonce('agah_ops_export_'.$cid.'_'.$type)])).'">دانلود '.$label.' ('.Money::unitLabel(Ctx::unit()).')</a>' ;}
}
